Please choose the most appropriate output for the following code

class Shape():
    def __init__(self):
        self.width = 5
        self.height = 5
    def get_area(self):
        return self.width * self.height / 2

class Triangle(Shape):
    def __init__(self, w, h):
        self.width = w
        self.height = h
    def __add__(self, other):
        return self.get_area() + other.get_area()

t1 = Triangle(10, 10)
t2 = Triangle(10, 10)
print(t1 + t2)

